mapper.select:
select 
   sum(t.share_amt) 
from TRD_PRODUCT_DEAL t
where t.finprod_id = #{finprodId,jdbcType=VARCHAR}

and t.trade_date >= to_date(#{netValueDate,jdbcType=VARCHAR}, 'yyyy-mm-dd')


 and t.trade_date >= to_date(#{dealDate,jdbcType=VARCHAR}, 'yyyy-mm-dd')

 and t.PS IN('C4')

    AND t.TRADE_STATUS = #{tradeStatus,jdbcType=VARCHAR}


    AND t.IS_CANCEL = #{isCancel,jdbcType=VARCHAR}

		select crule.pay_cycle payCycle, /*分红规则:01到期支付 02周期支付 07日付 08申购同频 09不规则*/
		       crule.pay_type payType, /*分红方式:01现金分红，02红利再投*/
		        min(cplan.mdate) mdate
		  from fin_cash_info cinfo
		 inner join fin_cash_pay_rule crule on cinfo.cash_id = crule.cash_id
		  left join fin_cash_plan cplan on cplan.cash_id = crule.cash_id
		  left join (
		      select max(trade_date) trade_date,#{finprodId,jdbcType=VARCHAR} finprod_id  
		        from trd_fin_product_deal_total f
		       where finprod_id = #{finprodId,jdbcType=VARCHAR}
		         and PS IN (#{PS_C9}, #{PS_C10}) 
		         and TRADE_STATUS= #{TRADE_STATUS01} 
		         and IS_CANCEL = #{YES_OR_NO_N} 
             ) f on f.finprod_id = cinfo.finprod_id
          	left join (
          	select DISTINCT finprod_id,trade_date,settle_date 
           		from trd_fin_product_deal_total
				where finprod_id = #{finprodId,jdbcType=VARCHAR}
		         and PS IN (#{PS_C9}, #{PS_C10}) 
		         and TRADE_STATUS= #{TRADE_STATUS01} 
		         and IS_CANCEL = #{YES_OR_NO_N} 
		         ) tot on tot.finprod_id = f.finprod_id
				and tot.trade_date = f.trade_date			
		   where cinfo.finprod_id = #{finprodId,jdbcType=VARCHAR}
		   and cinfo.cash_type_1 = #{cashType1,jdbcType=VARCHAR}
		   and cinfo.cash_type_2 = #{cashType2,jdbcType=VARCHAR}
		   AND NOT EXISTS (
				SELECT 1 FROM TRD_PRODUCT_DEAL
				WHERE cinfo.FINPROD_ID = TRD_PRODUCT_DEAL.FINPROD_ID
				AND cplan.MDATE = TRD_PRODUCT_DEAL.MDATE
				AND (TRD_PRODUCT_DEAL.PS = #{PS_C9} OR TRD_PRODUCT_DEAL.PS = #{PS_C10})
				AND TRD_PRODUCT_DEAL.IS_CANCEL = #{YES_OR_NO_N}
				AND TRD_PRODUCT_DEAL.TRADE_STATUS = #{TRADE_STATUS01}
			)



		   	and ((cplan.mdate > nvl(f.trade_date,cplan.vdate) and  cplan.mdate  <=  to_date(#{PlatformDay,jdbcType=DATE},'yyyy-MM-dd')) 
		   	or (cplan.mdate =  NVL(f.trade_date,cplan.vdate) and tot.SETTLE_DATE = to_date(#{PlatformDay,jdbcType=DATE},'yyyy-MM-dd'))
		   	or  crule.pay_cycle in (#{payCycle07},#{payCycle09}))



                and ((cplan.mdate > nvl(f.trade_date,cplan.vdate) and  cplan.mdate  <=  to_date(#{PlatformDay,jdbcType=DATE},'yyyy-MM-dd'))
                or(cplan.mdate =  NVL(f.trade_date,cplan.vdate) and tot.SETTLE_DATE = to_date(#{PlatformDay,jdbcType=DATE},'yyyy-MM-dd'))
                or crule.pay_cycle in (#{payCycle07},#{payCycle09}))



		   group by crule.pay_cycle,crule.pay_type

	select totle_trade_id totleTradeId
	  from TRD_FIN_PRODUCT_DEAL_TOTAL
	 where ps in ('C1', 'C2', 'C3', 'C4', 'C5', 'C6', 'C7', 'C8', 'C9', 'C10',
	        'C20', 'C17', 'C18')
	   AND TRADE_STATUS = '01'
	   AND IS_CANCEL = 'N'



			AND TRADE_DATE > #{subConfirmDate,jdbcType=DATE}		       


    		AND TRADE_DATE > #{purConfirmDate,jdbcType=DATE}


       		AND TRADE_DATE > #{redConfirmDate,jdbcType=DATE}


       		AND TRADE_DATE > #{expireConfirmDate,jdbcType=DATE}


       		AND TRADE_DATE > #{addReduceConfirmDate,jdbcType=DATE}





   			AND TRADE_DATE > #{subConfirmDate03,jdbcType=DATE}


       		AND TRADE_DATE > #{purConfirmDate03,jdbcType=DATE}


       		AND TRADE_DATE > #{redConfirmDate03,jdbcType=DATE}


       		AND TRADE_DATE > #{expireConfirmDate03,jdbcType=DATE}


       		AND TRADE_DATE > #{addReduceConfirmDate03,jdbcType=DATE}


       		AND TRADE_DATE > #{bonusCashEndDate03,jdbcType=DATE}


       		AND TRADE_DATE > #{bonusShareEndDate03,jdbcType=DATE}


	   AND FINPROD_ID = #{finprodId,jdbcType=VARCHAR}

	select totle_trade_id totleTradeId
	  from TRD_FIN_PRODUCT_DEAL_TOTAL
	 where ps like 'T%'
	   AND TRADE_STATUS = '01'
	   AND IS_CANCEL = 'N'		   


			AND TRADE_DATE > #{subConfirmDate,jdbcType=DATE}		       


    		AND TRADE_DATE > #{purConfirmDate,jdbcType=DATE}


       		AND TRADE_DATE > #{redConfirmDate,jdbcType=DATE}


       		AND TRADE_DATE > #{expireConfirmDate,jdbcType=DATE}


       		AND TRADE_DATE > #{addReduceConfirmDate,jdbcType=DATE}





   			AND TRADE_DATE > #{subConfirmDate03,jdbcType=DATE}


       		AND TRADE_DATE > #{purConfirmDate03,jdbcType=DATE}


       		AND TRADE_DATE > #{redConfirmDate03,jdbcType=DATE}


       		AND TRADE_DATE > #{expireConfirmDate03,jdbcType=DATE}


       		AND TRADE_DATE > #{addReduceConfirmDate03,jdbcType=DATE}


       		AND TRADE_DATE > #{bonusCashBonusDate03,jdbcType=DATE}


       		AND TRADE_DATE > #{bonusShareConfirmDate03,jdbcType=DATE}


	   AND FINPROD_ID = #{finprodId,jdbcType=VARCHAR}

select *
  from BOK_POSITION_PRD
 where cdate = (select max(cdate)
                  from BOK_POSITION_PRD
                 where finprod_id = #{finprodId,jdbcType=VARCHAR}
                   and branch = #{branch,jdbcType=INTEGER})
   and finprod_id = #{finprodId,jdbcType=VARCHAR}
   and branch = #{branch,jdbcType=INTEGER}

select count(1)
from ptl_sec_position t inner join fin_product r
 on t.finprod_id = r.finprod_id
where t.cdate = (select max(cdate)
                 from ptl_sec_position
                  where portfolio_id = #{portfolioId,jdbcType=VARCHAR}
                  and branch = #{branch,jdbcType=INTEGER}
                  and cdate <= #{ndate,jdbcType=DATE}
               )
  and t.portfolio_id = #{portfolioId,jdbcType=VARCHAR}
  and t.branch = #{branch,jdbcType=INTEGER}
  and r.finprod_type2 in ('F01','F07', 'F06', 'F18', 'F22')
   and t.amount != 0

	    select  distinct rule.PAY_TYPE from FIN_CASH_INFO  info  
            left join FIN_CASH_PAY_RULE rule
            on info.CASH_ID = rule.CASH_ID
            where  info.CASH_TYPE_1 = #{cashType1,jdbcType=VARCHAR}
            AND info.CASH_TYPE_2 = #{cashType2,jdbcType=VARCHAR}
            and info.FINPROD_ID = #{finprodId,jdbcType=VARCHAR}

	    select * from FIN_CASH_INFO 
            where FINPROD_ID = #{finProdId,jdbcType=VARCHAR} 
            AND BRANCH = #{finBrach,jdbcType=VARCHAR} 
            AND CASH_TYPE_1 = #{cashFree,jdbcType=VARCHAR} 
            AND CASH_TYPE_2 = #{cashManeFree,jdbcType=VARCHAR}

	    select * from FIN_CASH_CALC_RULE 
            where CASH_ID = #{timeCashId,jdbcType=VARCHAR} 
            AND EFF_DATE <=  #{vDate,jdbcType=DATE} ORDER BY EFF_DATE DESC

	    select * from FIN_FLOAT_CALC_RULE 
            where CASH_ID = #{timeCashId,jdbcType=VARCHAR} 
            AND EFF_DATE <=  #{vDate,jdbcType=DATE} ORDER BY EFF_DATE DESC

	    select * from FIN_FLOAT_CALC_RULE_DETAIL
            where CASH_ID = #{timeCashId,jdbcType=VARCHAR}  
            AND EFF_DATE <=  #{vDate,jdbcType=DATE} ORDER BY EFF_DATE DESC

	    select * from FIN_BASE_RULE_INFO
            where FINPROD_ID = #{finProdId,jdbcType=VARCHAR}  
            AND BRANCH = #{finBrach,jdbcType=INTEGER} 
            AND BASE_RULE_TYPE = #{finBaseRuleType,jdbcType=VARCHAR}  
            AND EFF_DATE <=  #{vDate,jdbcType=DATE} ORDER BY EFF_DATE DESC

		SELECT
    		TERM_MAX id,TERM_MAX text
		FROM PRD_LAYER_PARAM WHERE P_FINPROD_ID = #{finprodId}

		SELECT				
    		INT_AMT
		FROM
		    trd_product_deal
		where 
	    	totle_trade_id = #{tradeId,jdbcType=VARCHAR} 
	    	and busi_type = #{busiType2,jdbcType=VARCHAR} 
	    	and finprod_id = #{finprodId,jdbcType=VARCHAR} 
	    	and branch = #{branch,jdbcType=INTEGER}

		SELECT				
    		*
		FROM
		    FIN_TRADE_PRODUCT
		where 
		    1=1 

		    AND PERIOD_ID = #{periodId,jdbcType=VARCHAR}


		    AND FINPROD_ID = #{finprodId,jdbcType=VARCHAR}


		    AND VDATE = #{vDate,jdbcType=DATE}


		    AND MDATE = #{mDate,jdbcType=DATE}

select sum(FPRICE_AMT) from TRD_FIN_PRODUCT_DEAL_TOTAL where ps in (#{PS_09,jdbcType=VARCHAR},#{PS_10,jdbcType=VARCHAR}) 
AND FINPROD_ID  =  #{finprodId,jdbcType=VARCHAR}
and TRADE_DATE = to_date(#{netValueDate,jdbcType=VARCHAR}, 'yyyy-mm-dd')
AND TRADE_STATUS = #{TRADE_STATUS_01,jdbcType=VARCHAR} 
AND IS_CANCEL = #{IS_CANCEL_N,jdbcType=VARCHAR}
